import React, { useEffect, useState } from 'react';
import { recruiterApi } from '../services/api';
import { downloadResume } from '../utils/downloadResume';

export default function RecruiterSearch() {
  const [keyword, setKeyword] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);

  const loadAllCandidates = () => {
    setLoading(true);
    recruiterApi.getCandidates().then((res) => setResults(res.data)).finally(() => setLoading(false));
  };

  useEffect(() => { loadAllCandidates(); }, []);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!keyword.trim()) { loadAllCandidates(); return; }
    setLoading(true);
    try {
      const res = await recruiterApi.search(keyword.trim());
      setResults(res.data);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page-container">
      <h1>Candidate Search</h1>
      <p className="muted">Search by candidate name, skill, headline keyword, or location. Only resumes candidates have opted to share appear here.</p>
      <form onSubmit={handleSearch} className="search-bar">
        <input
          value={keyword}
          onChange={(e) => setKeyword(e.target.value)}
          placeholder="e.g. Priya Sharma, React, Chennai, Backend Developer"
        />
        <button type="submit">Search</button>
      </form>

      {loading && <p>Loading candidates…</p>}
      {!loading && results.length === 0 && <p>No matching candidates found.</p>}

      <div className="resume-grid">
        {results.map((r) => (
          <div className="resume-card" key={r.id}>
            <h3>{r.candidateName || 'Candidate name not provided'}</h3>
            <p className="muted" style={{ marginTop: '-6px', fontWeight: 600 }}>{r.headline || r.title}</p>
            <p className="muted">{r.location}</p>
            <p>{r.summary?.slice(0, 140)}{r.summary?.length > 140 ? '…' : ''}</p>
            <div className="skill-tags">
              {r.skills?.slice(0, 6).map((s) => <span key={s} className="skill-tag">{s}</span>)}
            </div>
            <div className="card-actions">
              <button
                type="button"
                className="btn-link"
                onClick={() => downloadResume(r)}
                title="Download / Print PDF"
              >
                Download Resume
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
